import org.eclipse.swt.SWT;
import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.custom.StyledText;

public class GCTextDrawingBefore {
    public static void main(String[] args) {
        Display display = new Display();
        Shell shell = new Shell(display);
        shell.setText("GC Draw Text Example");
        shell.setSize(300, 200);

        StyledText textWidget = new StyledText(shell, SWT.NONE);
        textWidget.setBounds(10, 10, 200, 50);
        textWidget.setText("Hello World");

        shell.open();

        GC gc = new GC(shell);
        try {
            Color red = display.getSystemColor(SWT.COLOR_RED);
            gc.setForeground(red);
            int x = 50;
            int y = 100;
            String title = "Test String";

            // The code to be transformed
            gc.drawText(title, x, y);

        } finally {
            gc.dispose();
        }

        while (!shell.isDisposed()) {
            if (!display.readAndDispatch()) {
                display.sleep();
            }
        }
        display.dispose();
    }
}

